import{_ as a,o as n,c as e,ai as t}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"第二层 · 软件开发生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/02-lifecycle.md","filePath":"ai/productivity/dev-spec/02-lifecycle.md"}'),i={name:"ai/productivity/dev-spec/02-lifecycle.md"};function r(p,s,l,d,o,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="第二层-·-软件开发生命周期" tabindex="-1">第二层 · 软件开发生命周期 <a class="header-anchor" href="#第二层-·-软件开发生命周期" aria-label="Permalink to “第二层 · 软件开发生命周期”">​</a></h1><blockquote><p>让开发过程规范。从项目准备到交付的九个阶段，按任务轻重裁剪：改文案直接做，复杂功能完整走。第三层的安全与变更控制贯穿这九步全程。</p></blockquote><h2 id="九阶段速查" tabindex="-1">九阶段速查 <a class="header-anchor" href="#九阶段速查" aria-label="Permalink to “九阶段速查”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>一句话</th><th>何时可跳过</th></tr></thead><tbody><tr><td>01 项目准备</td><td>让 AI 懂项目、定边界</td><td>小修改、已有上下文</td></tr><tr><td>02 需求分析</td><td>把目标、约束、验收说清</td><td>几乎不跳过</td></tr><tr><td>03 架构设计</td><td>先方案后编码</td><td>L1 简单任务</td></tr><tr><td>04 功能开发</td><td>连续执行、按范围改动</td><td>—</td></tr><tr><td>05 审查完善</td><td>按清单核对并补齐</td><td>小修改做局部检查</td></tr><tr><td>06 逻辑与 BUG 修复</td><td>排查闭环、最小修复</td><td>无问题则不涉及</td></tr><tr><td>07 优化重构</td><td>改善结构不改行为</td><td>无技术债可跳过</td></tr><tr><td>08 代码测试</td><td>按证据验证</td><td>—</td></tr><tr><td>09 交付复用</td><td>报告留痕、经验沉淀</td><td>小任务简化报告</td></tr></tbody></table><p>任务分级决定强度：<strong>L1</strong>（范围明确、影响小）直接做 + 局部检查；<strong>L2</strong>（多文件、有业务逻辑）先分析 + 简要方案；<strong>L3</strong>（多模块、核心业务、数据结构、高风险）完整分析 + 分阶段执行。判断标准：改错了要回滚多个文件就按 L3 走；改动一行但涉及订单状态、库存、资金也可能是 L3。</p><h2 id="_01-项目准备" tabindex="-1">01 项目准备 <a class="header-anchor" href="#_01-项目准备" aria-label="Permalink to “01 项目准备”">​</a></h2><p><strong>什么时候用</strong>：新项目初始化、接手老项目、AI 老理解错。 <strong>怎么做</strong>：新项目按「边界 → 结构 → 代码」——定目标用户、检查已有文件不覆盖、定命令并跑通、定规范与禁改区、只建必要资料。老项目只读理解（结构、命令、业务模块、接口数据、规则、风险），汇成带来源的接入报告，保护边界：不擅自重构、改接口签名、升级依赖、格式化无关文件、把推测当事实、删功能或动生产数据。 <strong>完成判据</strong>：五问能答上（改哪几个文件、谁受影响、哪张表哪个接口、为什么这么写、哪些不能碰）；新项目命令跑通、老项目无架构级改动。详见 <a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation.html">第一层 · Project Context</a>。</p><h2 id="_02-需求分析" tabindex="-1">02 需求分析 <a class="header-anchor" href="#_02-需求分析" aria-label="Permalink to “02 需求分析”">​</a></h2><p><strong>什么时候用</strong>：任何任务开始前。输入不是越详细越好，而是影响正确性的信息不能缺——能从项目查到的不让用户重写。</p><p><strong>任务输入六项</strong>：背景（视情况）、目标（必填）、约束（必填，说清能改不能改）、输出格式（必填）、任务分级（AI 判断）、验收标准（必填，简单可简写）。</p><p><strong>让 AI 主动补全</strong>：信息分三类——已确认（直接采用）、可推断（查证据后采用）、待确认（集中提问）。能从项目确认的不问用户；不影响正确性的细节按项目规范；涉及业务规则、数据一致性、权限、安全、不可逆的不能猜。阻塞问题一次性提完，没有就直接执行，不逐步问「要不要继续」。</p><blockquote><p>提示词 · 日常任务输入</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>任务：&lt;一句话&gt;　目标：&lt;预期结果&gt;　约束：&lt;能改/不能改/必须兼容&gt;　验收：&lt;怎样算完成&gt;</span></span>
<span class="line"><span>先读项目补全上下文，不要让我重写能从代码查到的信息。缺失信息分三类：能从项目确认的不问我；不影响正确性的按项目规范；涉及业务规则/数据/权限/安全/不可逆的不猜。</span></span>
<span class="line"><span>阻塞问题一次性提完，没有就直接执行。完成后给修改内容、验证证据、遗留风险。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>完成判据</strong>：需求已复述、边界与不做项清楚、验收可核对（不是「完成开发」）、关键疑点已确认。</p><h2 id="_03-架构设计" tabindex="-1">03 架构设计 <a class="header-anchor" href="#_03-架构设计" aria-label="Permalink to “03 架构设计”">​</a></h2><p><strong>什么时候用</strong>：L2/L3 任务，方案错了要回滚多个文件或改数据结构时。</p><p><strong>方案回答五维度</strong>：数据（表、索引、迁移、事务）、接口（路径、入出参、错误码、兼容）、模块分层、兼容影响（老数据、调用方、开关、定时任务）、验证方式。多方案比较改动范围/数据影响/兼容性/回滚成本/验证难度，取舍顺序：业务正确性 → 兼容性 → 改动范围 → 复用 → 可验证性 → 美观。</p><p><strong>必须写修改范围三栏</strong>：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>允许修改：&lt;具体文件路径&gt;</span></span>
<span class="line"><span>禁止修改：&lt;接口签名 / 历史目录 / 依赖文件&gt;</span></span>
<span class="line"><span>必须保持兼容：&lt;返回结构 / 状态机规则&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>同时写「本次不做项」。风险写成「风险→触发条件→影响→处理→谁确认」，不写「可能有风险」。通过后拆子任务：能独立完成、独立验收、一次提交覆盖，按 数据层→后端→接口→前端→测试→文档 排；前后端并行前提是契约先冻结。</p><blockquote><p>提示词 · 生成方案（本轮不改代码）</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>基于已有上下文产出技术方案和风险清单，本轮不改代码、不建文件。</span></span>
<span class="line"><span>输出：1 需求复述 2 影响实现的问题 3 本次不做项 4 方案比较 5 推荐方案与理由 6 修改范围三栏 7 风险清单 8 子任务拆解（编号/任务/文件/依赖/完成标准/验收方式）9 检查点 10 需我拍板的问题。</span></span>
<span class="line"><span>不要编造项目里不存在的组件，无法判断的标「待确认」。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>完成判据</strong>：五维度齐全、三栏落到路径、风险有处理人、子任务可独立验收。</p><h2 id="_04-功能开发" tabindex="-1">04 功能开发 <a class="header-anchor" href="#_04-功能开发" aria-label="Permalink to “04 功能开发”">​</a></h2><p><strong>怎么做</strong>：连续执行靠三样东西——<code>TASK-PLAN.md</code>（子任务/依赖/完成标准/不做项）、<code>PROGRESS.md</code>（每轮做了什么、命令输出、下一步）、<code>DECISIONS.md</code>（可选，小决定及依据）。状态用 <code>pending → in_progress → done/blocked/skipped</code>，<code>done</code> 要有证据。</p><p><strong>每轮固定六步</strong>：读状态 → 选一个 pending → 只做这一个 → 跑完成标准对应命令 → 写 PROGRESS → 验证通过再提交。</p><p><strong>人必须在场</strong>：业务规则多种解释、涉及权限/支付/资金/库存、删数据或不可逆操作、改接口签名、加核心依赖、动禁改区、到检查点。确认只需回答三件事：选哪个方案、加哪些边界、哪些风险不接受。</p><p><strong>立即停手信号</strong>：AI 说「顺手把…也改了」、开始改依赖或公共模块、同一问题多种解释、重复问已答问题、完成标准被放宽。中断后让 AI 读 PROGRESS 末尾接上，不重做已完成任务。</p><blockquote><p>提示词 · 启动连续执行</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>本轮先不写代码，只确认规则：每轮只做一个 pending 子任务；先读计划和进度状态；严格遵守不做项和范围，越界先停；完成后跑命令并原样记录输出；每轮写 PROGRESS 再提交；失败先说明假设为何错，同一错误建议最多试几轮，仍失败标 blocked；到检查点停下来等我确认；不要自己宣布整体完成。</span></span>
<span class="line"><span>规则可行就从 T1 开始第一轮。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>完成判据</strong>：每轮一个子任务、有命令输出、改动在范围内、有提交记录。</p><h2 id="_05-审查完善" tabindex="-1">05 审查完善 <a class="header-anchor" href="#_05-审查完善" aria-label="Permalink to “05 审查完善”">​</a></h2><p><strong>怎么做</strong>：按清单逐项核对，让 AI 只输出问题清单和依据，不修改、不宣布通过，最终由人判定。清单六项：逻辑与业务规则完整性、边界条件（空值/零值/重复/越权）；异常与事务；接口/字段/数据兼容性；权限与数据范围；测试覆盖与断言是否被放宽；改动范围（无关格式化、未用 import、调试打印、注释分支、遗留 TODO）。</p><p>发现的问题分两类：影响正确性 → 走 06 修复闭环；属于改进优化 → 放 07 重构，不在这轮顺手大改。</p><blockquote><p>提示词 · 审自己的改动</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>对本轮改动做审查自查，不修改文件、不宣布通过。输入：验收标准、范围与不做项、git diff。</span></span>
<span class="line"><span>按清单输出问题（每条给文件:行号和依据）：逻辑与边界、异常与事务、兼容性、权限与数据范围、测试与断言、改动范围里的调试代码/遗留 TODO。</span></span>
<span class="line"><span>输出「问题清单」和「需人确认的疑点」两部分，不要写「整体没问题可以合并」这类判定。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>完成判据</strong>：清单逐项过完、问题带行号依据、硬红线（硬编码/吞异常/放宽断言/数据特判/越界）为零。详见 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality.html">第三层 · 代码质量</a>。</p><h2 id="_06-逻辑与-bug-修复" tabindex="-1">06 逻辑与 BUG 修复 <a class="header-anchor" href="#_06-逻辑与-bug-修复" aria-label="Permalink to “06 逻辑与 BUG 修复”">​</a></h2><p><strong>两套方法</strong>：逻辑错误（结果与预期不符、无报错）先列根因假设、找证据排除；BUG 报错先收齐五类证据（复现步骤、完整堆栈、期望行为、环境、最近改动）。不能稳定复现就先别改代码，让 AI 输出能确认的复现条件、已排除项、可能原因排序。</p><p><strong>修复闭环</strong>：固定证据 → 根因分析 → 最小修复 → 测试验证 → 回归验证。终点不是「代码改了」，而是「有证据证明改对了、且没改坏别的」。判断是否真根因：修掉它能不能解释原始现象，解释不了就还不是。</p><p><strong>最小修复</strong>：只改根因那一处、改动文件尽量少、不改接口契约、不删不放宽现有测试、能解释现象。<strong>这些不是修复</strong>：硬编码绕过、吞异常、放宽断言、删用例、加特判。</p><p><strong>失败先分类</strong>：代码错误可重试有限轮次；环境问题标受限；认知问题（改 A 坏 B）停手回分析；需求冲突交人确认。回归做对照表，至少留一条「改前行为保持」的证据。</p><blockquote><p>提示词 · 根因分析（本轮只分析）</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>本轮只分析不改代码。问题：&lt;现象+报错原文&gt;　复现：&lt;步骤&gt;　相关改动：&lt;git diff&gt;　相关文件：&lt;调用链&gt;</span></span>
<span class="line"><span>输出四段：1 事实（只写有证据的）2 根因假设（几条、排序、每条写支持/反对证据和验证动作）3 排除过程 4 结论与修复范围（确认的根因；证据不足写「未确认」；最小文件清单；绝对不能改的地方）。</span></span>
<span class="line"><span>证据指到行号/日志/命令输出，不输出修复代码，不选最像的当结论。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>完成判据</strong>：根因能解释现象、修复只改根因、每轮有命令输出、回归含「已修复」和「保持」两类证据。</p><h2 id="_07-优化重构" tabindex="-1">07 优化重构 <a class="header-anchor" href="#_07-优化重构" aria-label="Permalink to “07 优化重构”">​</a></h2><p><strong>什么时候用</strong>：功能正确但结构差、有技术债，且不属于正确性 BUG。<strong>重构不是加功能也不是修 BUG</strong>——要改行为就拆两步：先重构（行为不变），再改行为。</p><p><strong>先补行为测试</strong>锁定当前行为（正常路径 + 关键边界），没测试的重构等于盲改。保持不变的：接口签名、返回结构、数据结构、字段含义、状态流转。</p><p><strong>小步可回退</strong>：一次改一个关注点、每步跑测试、不夹带格式化、不新增依赖、不改业务规则。技术债按「影响后续开发的程度 × 改动风险」排序，稳定不动的冷门模块可暂缓。交付前清理本次产生的临时文件、调试脚本、注释掉的旧代码。</p><blockquote><p>提示词 · 重构但不改行为</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>目标：改善内部结构，不改变外部行为。代码：&lt;粘贴&gt;</span></span>
<span class="line"><span>约束：1 接口/结构/字段/状态流转全不变 2 先列要补的行为测试，等我确认再动手 3 一次改一个关注点，每步跑测试 4 不夹带格式化、注释改写、无关调整 5 不新增依赖、不改业务规则。</span></span>
<span class="line"><span>本轮输出：重构计划 + 行为测试清单 + 每步验证方式，先不要改代码。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>完成判据</strong>：有行为测试保护、外部行为不变、每步有测试、diff 能看清语义变化。</p><h2 id="_08-代码测试" tabindex="-1">08 代码测试 <a class="header-anchor" href="#_08-代码测试" aria-label="Permalink to “08 代码测试”">​</a></h2><p><strong>分层</strong>：单元（单函数/规则/边界，业务逻辑改动必补）、集成（模块协作/数据库/接口）、端到端冒烟（关键路径，交付前）。按任务级别裁剪强度。</p><p><strong>补测重点</strong>：覆盖正常 + 失败路径、边界（空值/零值/重复/越权）、断言精确不恒真、不为变绿而放宽或删用例。执行顺序：编译/类型检查 → 出问题的那个测试 → 相关模块 → 接口冒烟 → 全量。</p><p><strong>四态报告</strong>（最重要纪律）：已验证（有命令和输出证据）、未验证（说明原因和替代检查）、受限（环境权限不允许）、不适用（本次不涉及）。<strong>没输出的「已测试」等于没测试，没跑的不能写成通过。</strong></p><blockquote><p>提示词 · 补测试与回归清单</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>基于本次改动产出测试与回归清单，本轮只出清单不执行。</span></span>
<span class="line"><span>列出：1 必跑项（编译/类型检查/相关单测/接口冒烟，写具体命令）2 回归项（哪些原有功能必须不变、怎么验证）3 边界项（空值/权限/状态/并发）4 无法自动化的人工核对项。</span></span>
<span class="line"><span>每项给「检查点→预期→验证方式」，标出哪些是「漏了就出事」建议固化为脚本。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>完成判据</strong>：测试覆盖失败路径、有命令输出证据、四态分清、回归覆盖原有功能不变。详见 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality.html">第三层 · 测试与验证</a>。</p><h2 id="_09-交付复用" tabindex="-1">09 交付复用 <a class="header-anchor" href="#_09-交付复用" aria-label="Permalink to “09 交付复用”">​</a></h2><p><strong>底线：完成由人判定，不由 AI 宣布。</strong> AI 提供证据，人逐条核对。</p><p><strong>四层验收</strong>：功能（要求实现了吗）、兼容（原功能受影响吗）、技术（编译测试过了吗）、交付（可追溯可接手吗，含 diff 和报告）。任务输入的验收标准逐条抄来填预期/实际/证据/结论，「看起来没问题」不是证据。</p><blockquote><p>提示词 · 验收自查（不宣布完成）</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>本轮做验收自查，不修改文件、不宣布完成。输入：验收标准、范围与不做项、git diff、已执行命令与输出。</span></span>
<span class="line"><span>按四层输出：1 功能（逐条给证据或缺证据）2 兼容（没变/已确认兼容/需通知下游）3 技术（命令与输出关键行，未执行的标出不得写通过）4 交付（改动清单、遗留、是否可接手）。</span></span>
<span class="line"><span>另查 Git 安全（是否保留用户改动、是否触禁改区）和安全项（敏感信息、破坏性操作、输入校验）。</span></span>
<span class="line"><span>最后输出「可以进入人工验收 / 尚缺以下证据」二选一。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>交付报告</strong>至少含：任务与范围、完成内容、修改文件（改了什么+为什么）、验证证据（命令+输出关键行）、回归对照、安全结论、遗留问题（是什么+影响+建议+谁决定）、本次沉淀去向。</p><p><strong>经验复用三问</strong>：还会再出现吗？不沉淀代价是什么？有没有第二处验证？都答是才沉淀——跨任务约束进 Rules、踩过的坑进 known-issues、反复做法进 Skill、项目事实进认知资料、一次性过程留报告不沉淀。</p><p><strong>完成判据</strong>：四层验收有证据、完成由人判定、遗留问题有去处有人负责、沉淀经过三问。详见 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality.html">第三层 · 交付追踪回滚</a>。</p><hr><p>九阶段走完。全程的硬约束由第三层把关。回到 <a href="/my-vitepress-site/ai/productivity/dev-spec/">总览</a> · 上一层 <a href="/my-vitepress-site/ai/productivity/dev-spec/01-foundation.html">第一层 · AI 工程基础</a> · 下一层 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality.html">第三层 · 质量与安全保障</a>。</p>`,69)])])}const b=a(i,[["render",r]]);export{h as __pageData,b as default};
